function initFiltersAndSearch(){const e=document.getElementById("search-input"),t=document.getElementById("filter-metal"),n=document.getElementById("filter-period"),l=document.getElementById("filter-region"),r=document.getElementById("filter-script"),i=document.getElementById("btn-reset");function s(){const i=e.value.toLowerCase().trim(),s=t.value,a=n.value,o=l.value,d=r.value;renderResults(ALL_COINS_DATASET.filter(e=>{const t=!i||e.name.toLowerCase().includes(i)||e.ruler.toLowerCase().includes(i)||e.description.toLowerCase().includes(i)||e.metal.toLowerCase().includes(i)||e.script.toLowerCase().includes(i)||e.symbol.toLowerCase().includes(i),n="all"===s||e.metal===s,l="all"===a||e.period.includes(a),r="all"===o||e.region.includes(o),c="all"===d||e.script.includes(d);return t&&n&&l&&r&&c}))}e&&"undefined"!=typeof ALL_COINS_DATASET&&(e.addEventListener("input",s),t.addEventListener("change",s),n.addEventListener("change",s),l.addEventListener("change",s),r.addEventListener("change",s),i&&i.addEventListener("click",()=>{e.value="",t.value="all",n.value="all",l.value="all",r.value="all",s()}),s())}function renderResults(e){const t=document.getElementById("results-grid"),n=document.getElementById("results-count");t&&n&&(n.textContent=`Showing ${e.length} coin${1===e.length?"":"s"}`,0!==e.length?t.innerHTML=e.map(e=>`\n        <div class="result-card">\n            <span class="card-badge">🪙 ${e.metal} • ${e.period}</span>\n            <h3>${e.name}</h3>\n            <p><strong>Ruler/Authority:</strong> ${e.ruler}</p>\n            <p><strong>Region:</strong> ${e.region}</p>\n            <p><strong>Script & Symbol:</strong> ${e.script} • ${e.symbol}</p>\n            <p class="card-desc">${e.description}</p>\n            <a href="${e.url}" class="card-link">View Explorer →</a>\n        </div>\n    `).join(""):t.innerHTML='\n            <div class="empty-msg">\n                <h3>No coins match your search criteria</h3>\n                <p>Try clearing filters or searching with a different keyword like "Gold", "Maratha", or "Devanagari".</p>\n            </div>\n        ')}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const t=document.body.classList.toggle("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{initFiltersAndSearch(),initThemeToggle()});